-- ══════════════════════════════════════════════════════════════════
-- 채움 패키지 355개
-- ══════════════════════════════════════════════════════════════════
--
-- 값이 아니라 **계수**를 싣는다. 아래 두 INSERT 가 46,150 행 가까이를 만들어 낸다.
--
-- 공식은 dataset.ts 의 seriesOf()/pointMetric() 의 filler 분기와 **글자 그대로 같아야 한다.**
-- 한쪽만 고치면 mock 과 서버가 다른 숫자를 그리고, 그 차이는 구현 버그로 오해된다.
--   value(i) = GREATEST(0, latest - step * (last_idx - i))

CREATE TEMP TABLE filler_coef (
  package_id INT, start_index INT,
  dl_latest BIGINT, dl_step INT,
  dep_latest INT, dep_step INT,
  stars INT, stars_per_week INT, open_issues INT,
  major_top TEXT, major_prev TEXT, version_top TEXT, version_prev TEXT
) ON COMMIT DROP;

