  (363, 0, 3965802, 825, 6002, 8, 25852, 19, 202, '5', '4', '5.6.4', '4.0.0'),
  (364, 35, 227365, 1520, 27565, 12, 7415, 14, 165, '8', '7', '8.0.5', '7.0.0'),
  (365, 0, 2002316, 1389, 2516, -2, 22366, 3, 316, '2', '1', '2.7.1', '1.0.0'),
  (366, 0, 3291423, 527, 1623, -1, 31473, 8, 223, '2', '1', '2.11.1', '1.0.0'),
  (367, 0, 430208, 876, 10408, 6, 10258, 20, 208, '8', '7', '8.19.3', '7.0.0'),
  (368, 0, 1616401, 1150, 16601, 3, 36451, 7, 1, '4', '3', '4.7.2', '3.0.0'),
  (369, 0, 3069686, 810, 9886, 7, 9736, 17, 86, '2', '1', '2.2.3', '1.0.0');

-- 스냅샷에 0-기반 인덱스를 붙인다. dataset.ts 의 ALL_SNAPSHOTS 인덱스와 같다.
CREATE TEMP VIEW snap_idx AS
SELECT snapshot_at,
       (ROW_NUMBER() OVER (ORDER BY snapshot_at) - 1)::INT AS idx,
       ((SELECT count(*) FROM snapshot) - 1)::INT AS last_idx
FROM snapshot;

INSERT INTO package_snapshot (package_id, snapshot_at, downloads, stars, open_issues)
SELECT f.package_id, s.snapshot_at,
       GREATEST(0, f.dl_latest - f.dl_step::BIGINT * (s.last_idx - s.idx)),
       GREATEST(0, f.stars - f.stars_per_week * (s.last_idx - s.idx)),
       f.open_issues
FROM filler_coef f JOIN snap_idx s ON s.idx >= f.start_index;

-- major 는 둘이고 비율이 floor(v/3) : v - floor(v/3) 이다.
-- 정수 나눗셈만 쓰므로 반올림이 끼어들지 않는다 — TS 의 Math.floor 와 결과가 같다.
INSERT INTO package_version_snapshot (package_id, version, snapshot_at, dependents_count)
SELECT f.package_id, v.version, s.snapshot_at, v.cnt
FROM filler_coef f
JOIN snap_idx s ON s.idx >= f.start_index
CROSS JOIN LATERAL (
  SELECT GREATEST(0, f.dep_latest - f.dep_step * (s.last_idx - s.idx)) AS total
) t
CROSS JOIN LATERAL (VALUES
  (f.version_top,  t.total - (t.total / 3)),
  (f.version_prev, t.total / 3)
) AS v(version, cnt)
WHERE v.version IS NOT NULL AND v.cnt > 0;

COMMIT;

